import{_ as a,o as e,c as p,i as t}from"./app.97a355c7.js";const m=JSON.parse('{"title":"\u7761\u4E2A\u597D\u89C9 - Hackday\u9879\u76EE\u8BB0\u5F55","description":"","frontmatter":{},"headers":[],"relativePath":"pages/explore/share/\u7761\u4E2A\u597D\u89C9 - Hackday\u9879\u76EE\u8BB0\u5F55.md","lastUpdated":1786960924000}'),_={name:"pages/explore/share/\u7761\u4E2A\u597D\u89C9 - Hackday\u9879\u76EE\u8BB0\u5F55.md"},c=t('<h1 id="\u7761\u4E2A\u597D\u89C9-hackday\u9879\u76EE\u8BB0\u5F55" tabindex="-1">\u7761\u4E2A\u597D\u89C9 - Hackday\u9879\u76EE\u8BB0\u5F55 <a class="header-anchor" href="#\u7761\u4E2A\u597D\u89C9-hackday\u9879\u76EE\u8BB0\u5F55" aria-hidden="true">#</a></h1><blockquote><p>\u961F\u4F0D\u540D\u79F0: \u7761\u4E2A\u597D\u89C9</p><p>\u9879\u76EE\u540D\u79F0: \u57FA\u4E8E ESP32 \u7684\u7A7A\u6C14\u4EFF\u771F\u4E0E\u667A\u80FD\u8054\u52A8</p><p>\u672C\u6587\u4E3B\u8981\u8BB0\u5F55\u4E0B\u81EA\u5DF1 hackday \u9879\u76EE\u7075\u611F\u7684\u524D\u56E0\u540E\u679C\u4E0E\u672A\u6765\u5C55\u671B</p></blockquote><p>\u8FD9\u4E2A\u60F3\u6CD5\u6700\u5F00\u59CB\u6E90\u4E8E\u5728\u6296\u97F3\u5237\u5230\u7684\u4E00\u4E2A\u89C6\u9891, \u89C6\u9891\u4E2D\u662F\u4E00\u4E2A\u4EBA\u57FA\u4E8E\u7A7A\u6C14\u6D41\u52A8(\u6E4D\u6D41)\u505A\u4E86\u5BA4\u5185\u7684\u98CE\u6C34\u8BC4\u4F30, \u8BC4\u8BBA\u533A\u6709\u4EBA\u63D0\u51FA\u89C2\u70B9\u8BF4\u4E2D\u56FD\u53E4\u4EE3\u7684\u98CE\u6C34\u5176\u5B9E\u5C31\u662F\u98CE\u548C\u6C34\u4E4B\u95F4\u7684\u4EA4\u878D, \u4E5F\u5C31\u662F\u8BF4\u8C1C\u5E95\u5C31\u5728\u8C1C\u9762. \u98CE\u6C34\u4E3B\u8981\u5C31\u662F\u98CE\u548C\u6C34\u7684\u5E03\u5C40, \u78C1\u573A\u7684\u76F8\u4E92\u5F71\u54CD, \u6211\u5BF9\u8FD9\u4E2A\u4E5F\u662F\u6BD4\u8F83\u8BA4\u540C\u7684, \u6240\u4EE5\u5C31\u8BB0\u4E86\u4E0B\u6765.</p><p>\u540C\u65F6\u81EA\u5DF1\u524D\u6BB5\u65F6\u95F4\u5728\u79DF\u7684\u623F\u5B50\u91CC\u590F\u5929\u73A9\u6E38\u620F, \u7A7A\u8C03\u5B89\u88C5\u7684\u4F4D\u7F6E\u4E0D\u592A\u597D, \u5C31\u5BFC\u81F4\u5F00\u4E86\u7A7A\u8C03\u5439\u7684\u4EBA\u51B7, \u4E0D\u5F00\u623F\u95F4\u53C8\u70ED, \u8BA9\u4EBA\u5F88\u82E6\u607C, \u6211\u5C31 get \u5230\u7A7A\u8C03\u4F4D\u7F6E\u7684\u9009\u62E9\u771F\u7684\u662F\u4E00\u4EF6\u5F88\u91CD\u8981\u7684\u4E8B\u60C5, \u5DEE\u7684\u4F4D\u7F6E\u5BF9\u7740\u4EBA\u5439\u592A\u96BE\u53D7\u4E86, \u623F\u95F4\u7684\u5E03\u5C40\u4E00\u5B9A\u8981\u8003\u8651\u4E0B\u7A7A\u8C03\u8FD9\u79CD\u786C\u88C5\u7535\u5668\u7684\u5B89\u88C5.</p><p>\u540E\u6765\u53C8\u5237\u5230\u4E86\u4E00\u4E2A\u5C71\u95F4\u5C0F\u623F\u5B50\u4E0D\u540C\u671D\u5411\u65F6\u98CE\u5BF9\u6574\u4E2A\u4F4F\u5B85\u7684\u5F71\u54CD, \u52A0\u6DF1\u4E86\u8FD9\u4E2A\u5370\u8C61. \u6B63\u597D\u516C\u53F8\u5F00\u59CB\u4E3E\u529E hackday \u6D3B\u52A8(\u4E00\u4E2A\u5927\u5BB6\u81EA\u7531\u62A5\u540D\u8111\u6D1E\u5927\u5F00\u505A\u9879\u76EE\u7684\u6D3B\u52A8), \u6211\u5C31\u60F3\u7740\u8FD9\u4E0D\u6B63\u597D\u501F\u52A9\u516C\u53F8\u7684\u6237\u578B\u6570\u636E\u7136\u540E\u52A0\u4E0A AI \u7684\u80FD\u529B\u8FDB\u884C\u5BA4\u5185\u6C14\u4F53\u4EFF\u771F, \u6211\u57FA\u4E8E\u8FD9\u4E2A\u4EFF\u771F\u7ED3\u679C\u770B\u4E0B\u5BA4\u5185\u54EA\u91CC\u7A7A\u6C14\u6D41\u52A8\u597D, \u54EA\u91CC\u9002\u5408\u5B89\u88C5\u51FA\u98CE\u53E3, \u4E3A\u6574\u4F53\u88C5\u4FEE\u505A\u4E00\u4E9B\u53C2\u8003, \u4E8E\u662F\u6211\u5C31\u62A5\u540D\u4E86.</p><p>\u62A5\u540D\u4E4B\u521D\u6211\u7684\u60F3\u6CD5\u5C31\u662F\u7B80\u5355\u7684\u5BA4\u5185\u7A7A\u6C14\u6A21\u62DF\u4EFF\u771F, \u53EA\u51FA\u65B9\u6848; \u540E\u9762\u505A\u7740\u505A\u7740\u611F\u89C9\u8FD9\u4E2A\u9700\u6C42\u6709\u4E9B\u5355\u8584, \u6CA1\u6709\u771F\u5B9E\u7684\u7ACB\u8DB3\u70B9, \u53EA\u505A\u4EFF\u771F\u6CA1\u6709\u540E\u7EED\u884C\u52A8\u5F88\u5BB9\u6613\u843D\u7A7A. \u4E8E\u662F\u6211\u5C31\u5F00\u59CB\u60F3\u6709\u6CA1\u6709\u5176\u4ED6\u65B9\u6848, \u60F3\u4E86\u597D\u4E45\u540E, \u6211\u51B3\u5B9A\u52A0\u4E0A\u4E00\u4E2A\u786C\u4EF6, \u4ECE\u7A7A\u6C14\u4EFF\u771F\u8FD9\u4E00\u4E2A\u70B9\u5207\u5165\u6574\u4E2A\u7A7A\u95F4\u667A\u80FD. \u5F53\u524D\u65B9\u6848\u7684 mvp \u662F\u6211\u5148\u505A\u4EFF\u771F, \u7136\u540E\u623F\u5B50\u88C5\u4FEE\u597D\u540E\u771F\u6B63\u5165\u4F4F\u4E86, \u57FA\u4E8E\u786C\u4EF6\u5B9E\u65F6\u76D1\u63A7\u5BA4\u5185\u7684\u7A7A\u6C14, \u6BD4\u5982 CO2 \u6D53\u5EA6, \u81EA\u52A8\u52A0\u5927\u901A\u98CE\u7B49. \u4E4B\u524D\u6709\u4F1A\u8BAE\u8001\u677F\u8BF4\u5927\u5BB6\u5728\u7528 AI \u73A9\u8F6F\u4EF6\u7684\u540C\u65F6\u4E5F\u53EF\u4EE5\u52A0\u4E0A\u4E00\u4E9B\u786C\u4EF6, \u6240\u4EE5\u65B0\u7684\u9700\u6C42\u5C31\u8FD9\u6837\u8BDE\u751F\u4E86: \u524D\u7F6E\u5BA4\u5185\u7A7A\u6C14\u4EFF\u771F + \u540E\u7F6E\u5BB6\u5C45\u667A\u80FD\u8C03\u8282.</p><p>\u65B9\u6848\u5177\u4F53\u5185\u5BB9\u4E3A:</p><p>\u5728\u8BBE\u8BA1\u5DE5\u5382\u7684\u6E32\u67D3\u9875, \u9009\u62E9\u6B63\u4EA4\u89C6\u89D2, \u968F\u540E\u70B9\u51FB\u8FDB\u5165\u7A7A\u6C14\u6D41\u52A8\u5206\u6790, \u7528\u6237\u53EF\u4EE5\u67E5\u770B\u623F\u95F4\u7A7A\u6C14\u6D41\u52A8\u65B9\u5411, \u6C14\u4F53\u6D41\u52A8, \u589E\u52A0\u51FA\u98CE\u53E3, \u5BF9\u6BD4\u4E0D\u540C\u51FA\u98CE\u53E3\u6548\u679C, \u4E5F\u53EF\u4EE5\u8BBE\u7F6E\u4F20\u611F\u5668\u91C7\u96C6\u70B9.</p><p>\u76F8\u6BD4\u4E8E\u6700\u5F00\u59CB\u7684\u5355\u4E00\u4EFF\u771F\u65B9\u6848, \u6211\u81EA\u5DF1\u53C8\u6784\u601D\u4E86\u4E0B, \u628A\u6700\u65B0\u65B9\u6848\u5305\u88C5\u6210\u5B83\u662F\u4E00\u6574\u5957\u5BA4\u5185\u5065\u5EB7\u7A7A\u6C14\u89E3\u51B3\u65B9\u6848. \u8FD9\u6837\u7684\u597D\u5904\u662F\u5305\u88C5\u540E\u65E2\u53EF\u4EE5\u5C06\u4E00\u4E9B\u9AD8\u5927\u4E0A\u7684\u4E1C\u897F, \u5356\u6982\u5FF5, \u4E5F\u6709\u540E\u7EED\u7684\u843D\u5730, \u5982\u786C\u4EF6\u7684\u5B89\u88C5\u8C03\u8BD5\u4E0E\u552E\u5356. \u53E6\u4E00\u65B9\u9762, \u65B0\u7684\u89E3\u51B3\u65B9\u6848\u9762\u5411\u5BA2\u6237\u4E0D\u5728\u5C40\u9650\u4E8E\u65E7\u65B9\u6848\u7684\u65B0\u623F\u88C5\u4FEE, \u65E7\u623F\u667A\u80FD\u5316\u6539\u9020\u4E5F\u9002\u7528, \u6269\u5927\u4E86\u5BA2\u6237\u7FA4\u4F53. \u6700\u540E, \u5C31\u662F\u8FD9\u4E2A\u89E3\u51B3\u65B9\u6848\u5BF9\u4E8E\u88C5\u4FEE\u516C\u53F8\u4E5F\u662F\u4E00\u4E2A\u65B0\u7684\u6210\u957F\u65B9\u5411, \u968F\u7740\u751F\u6D3B\u4E0E\u79D1\u6280\u6C34\u5E73\u7684\u63D0\u9AD8, \u5927\u5BB6\u80AF\u5B9A\u4F1A\u8FFD\u6C42\u66F4\u8212\u670D\u4E0E\u667A\u80FD\u7684\u751F\u6D3B, \u6574\u5C4B\u667A\u80FD\u5BB6\u5C45\u9886\u57DF\u8FD8\u662F\u5F88\u6709\u6210\u957F\u6F5C\u529B\u7684. \u6211\u4EEC\u5E38\u8BF4\u7A7A\u95F4\u667A\u80FD, \u516C\u53F8\u7684\u6237\u578B\u6570\u636E + SP \u6A21\u578B + \u667A\u80FD\u786C\u4EF6\u4E00\u5B9A\u662F\u80FD\u591F\u5F88\u597D\u843D\u5730\u7684.</p><p>\u6700\u540E, \u6211\u81EA\u5DF1\u8FD8\u6709\u4E00\u4E2A\u8FDC\u671F\u7684\u5C55\u671B, \u968F\u7740 AI \u7684\u53D1\u5C55, \u5404\u79CD\u8F6F\u786C\u4EF6\u7684\u521B\u65B0\u80AF\u5B9A\u4F1A\u8D8A\u6765\u8D8A\u591A, \u4F46\u662F\u5BF9\u4E8E\u5C0F\u767D\u6765\u8BF4\u786C\u4EF6\u7684\u7EC4\u88C5\u548C\u9009\u62E9\u8FD8\u662F\u4E00\u5927\u95E8\u69DB, \u672A\u6765\u662F\u4E0D\u662F\u53EF\u4EE5\u53D1\u5C55\u6A21\u5757\u5316\u786C\u4EF6, \u6BD4\u5982\u5F00\u53D1\u4E00\u4E2A\u5E73\u53F0, \u53EA\u552E\u5356\u6A21\u5757\u5316\u7535\u5B50\u5668\u4EF6, \u53EF\u4EE5\u8BA9\u7528\u6237\u81EA\u5DF1\u9009\u62E9\u8FD9\u4E2A\u5668\u4EF6\u4E2D\u7528\u54EA\u4E9B\u4F20\u611F\u5668, \u7535\u6C60, \u5F00\u53D1\u677F, \u901A\u4FE1\u534F\u8BAE, \u7528\u6237\u4E0D\u7528\u81EA\u5DF1\u53BB\u6253\u677F, \u5236\u4F5C\u5916\u58F3, \u7C7B\u4F3C\u4E8E\u4E4B\u524D\u7684\u6A21\u5757\u5316\u7535\u8111\u5E73\u53F0. \u53E6\u5916\u4E00\u4E2A\u70B9\u5C31\u662F\u516C\u53F8\u7684 sp \u6A21\u578B, \u6211\u89C9\u5F97\u53EF\u4EE5\u628A\u5B83\u505A\u6210\u6574\u4E2A\u667A\u80FD\u5BB6\u5177\u7684\u7F51\u5173\u4E2D\u5FC3, \u5229\u7528\u5176\u7A7A\u95F4\u611F\u77E5\u7684\u80FD\u529B\u548C\u76F8\u5173\u786C\u4EF6\u4F20\u611F\u5668\u5B9E\u73B0\u66F4\u667A\u80FD\u7684\u6548\u679C, \u7136\u540E\u5177\u4F53\u7684\u667A\u80FD\u6570\u636E\u4E5F\u80FD\u7528\u6765\u53CD\u54FA\u6A21\u578B\u7684\u8FED\u4EE3.\u5F53\u7136\u6211\u81EA\u5DF1\u73B0\u5728\u601D\u7EF4\u8DDF\u4E0D\u4E0A, \u4E5F\u8FD8\u6CA1\u60F3\u5230\u5177\u4F53\u53EF\u843D\u5730\u7684\u573A\u666F.</p>',10),o=[c];function s(d,r,n,h,i,l){return e(),p("div",null,o)}const y=a(_,[["render",s]]);export{m as __pageData,y as default};
